namespace ghidra.framework.main.datatree;





using docking.tool;
using generic.theme;
using ghidra.framework.client;
using ghidra.framework.client;
using ghidra.framework.model;
using resources;

public class DomainFolderRootNode : DomainFolderNode, RemoteAdapterListener {

	private static readonly Icon CLOSED_PROJECT = new GIcon("icon.datatree.node.domain.folder.closed");
	private static readonly Icon OPEN_PROJECT = new GIcon("icon.datatree.node.domain.folder.open");

	private static readonly Icon CONNECTED_OVERLAY =
		new GIcon("icon.project.root.repo.connected.overlay");
	private static readonly Icon DISCONNECTED_OVERLAY =
		new GIcon("icon.project.root.repo.disconnected.overlay");

	private static class Status
{	public static readonly Status OPEN = new(true);
	public static readonly Status CLOSED = new(false);
	public static readonly Status OPEN_CONNECTED = new(true, true);
	public static readonly Status CLOSED_CONNECTED = new(false, true);
	public static readonly Status OPEN_DISCONNECTED = new(true, false);
	public static readonly Status CLOSED_DISCONNECTED = new(false, false);


		Icon icon;

		private Status(bool isOpen) {
			icon = isOpen ? OPEN_PROJECT : CLOSED_PROJECT;
		}

		private Status(bool isOpen, bool isConnected) {
			MultiIcon multiIcon = new MultiIcon(isOpen ? OPEN_PROJECT : CLOSED_PROJECT);
			multiIcon.addIcon(isConnected ? CONNECTED_OVERLAY : DISCONNECTED_OVERLAY);
			icon = multiIcon;
		}

		static Status getStatus(bool isOpen, RepositoryAdapter repository) {
			if (isOpen) {
				if (repository == null) {
					return OPEN;
				}
				return repository.isConnected() ? OPEN_CONNECTED : OPEN_DISCONNECTED;
			}
			if (repository == null) {
				return CLOSED;
			}
			return repository.isConnected() ? CLOSED_CONNECTED : CLOSED_DISCONNECTED;
		}
	}

	private string projectName;
	private RepositoryAdapter repository;

	private Status status;
	private string toolTipText;

	DomainFolderRootNode(string projectName, DomainFolder rootFolder, ProjectData projectData,
			DomainFileFilter filter) : base(rootFolder, filter)
    {
		this.projectName = projectName;
		this.repository = getProjectData().getRepository();
		if (repository != null) {
			repository.addListener(this);
		}

		toolTipText = getToolTip(projectData);
	}

	/* @Override */
	public void dispose() {
		if (repository != null) {
			repository.removeListener(this);
		}
		base.dispose();
	}

	/* @Override */
	public string getName() {
		if (projectName == null) {
			return ToolConstants.NO_ACTIVE_PROJECT;
		}
		return projectName;
	}

	void setName(string newName) {
		projectName = newName;
		fireNodeChanged();
	}

	/* @Override */
	public string getToolTip() {
		return toolTipText;
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		status = Status.getStatus(expanded, repository);
		return status.icon;
	}

	private string getToolTip(ProjectData projectData) {
		ProjectLocator projectLocator = projectData.getProjectLocator();
		File dir = projectLocator.getProjectDir();
		string toolTip = dir.getAbsolutePath();
		if (!projectLocator.isTransient() && repository != null) {
			ServerInfo info = repository.getServerInfo();
			string serverName = info.getServerName() + ":";
			string statusText = repository.isConnected() ? "connected" : "disconnected";
			toolTip += " [" + serverName + repository.getName() + ", " + statusText + "]";
		}
		return toolTip;
	}

	/* @Override */
	public void connectionStateChanged(object adapter) {
		toolTipText = getToolTip(getProjectData());
	}
}
